// /98
static bool xmqcli_r2(xmqcli_Parser *p, void *elem, xmqcli_Buf *attr)
{
    // Greedy loop over a character table.
    for (;;)
    {
        int c = xmqcli_peek(p, p->pos);
        if (xmqcli_inset(xmqcli_set_0, 3, xmqcli_ascii_0, c))
        {
            p->pos++;
            continue;
        }
        if (!xmqcli_inset(xmqcli_set_1, 2, xmqcli_ascii_1, c)) return xmqcli_fail(p, "ws", NULL);
        return true;
    }
}

